mapper.select:
select id,appVerCode,layerName,url,code,industry_code from sys_applayer_url where 1 = 1

    AND industry_code = #{industryCode}

order by code

SELECT DISTINCT #{orgId} as deptId,town_code as streetAreaCode,province_id as provinceCode,city_id as cityCode,county_id as countyCode,'0' as type FROM vm_device_info_t WHERE delete_flag = '0'
AND device_code in

    #{item}

SELECT DISTINCT #{orgId} as deptId,street_code as streetAreaCode,province_code as provinceCode,city_code as cityCode,county_code as countyCode,'0' as type FROM vm_organ_street_rel_t  WHERE delete_flag = '0'
AND street_code in

    #{item.streetCode}

SELECT DISTINCT area_code as streetId,area_parent_code as countyId FROM sys_area WHERE status = '0'
AND area_code in

    #{item}

SELECT DISTINCT province_code,city_code,county_code FROM sys_dept_street_rel WHERE
dept_id in

    #{item}

SELECT DISTINCT a.area_code, a.area_name, a.area_level, a.area_parent_code, a.area_parent_name, a.longitude, a.latitude, a.status, a.create_by, a.create_time, a.update_by, a.update_time, a.dept_id,a.bussness_unit FROM sys_area a , sys_dept_street_rel b WHERE (a.AREA_CODE = b.PROVINCE_CODE OR a.AREA_CODE = b.CITY_CODE OR a.AREA_CODE = b.COUNTY_CODE) AND b.DEPT_ID IN
#{item}
ORDER BY a.AREA_CODE

SELECT DISTINCT a.area_code, a.area_name, a.area_level, a.area_parent_code, a.area_parent_name, a.longitude, a.latitude, a.status, a.create_by, a.create_time, a.update_by, a.update_time, a.dept_id,a.bussness_unit FROM sys_area a where a.AREA_CODE
#{item}
ORDER BY a.AREA_CODE

