DELETE FROM vm_screen_data_config WHERE
screen_data_config_id = #{item.countId}
AND data_type = #{item.dataType}
AND data_code = #{item.dataCode}

    AND data_source = #{item.dataSource}

mapper.delete:
DELETE FROM vm_organ_alarm_type_rel_t
WHERE delete_flag = 0
AND (

    (tenant_id = #{item.tenantId}
    AND dept_id = #{item.deptId}
    AND warning_source = #{item.warningSource}
    AND type_value = #{item.typeValue}
    AND industry_code = #{item.industryCode}
    AND app_ver_code = #{item.appVerCode})

)

mapper.select:
SELECT id as screenDataConfigId, alarm_type_num FROM vm_screen_data_config_count WHERE id IN
#{id}
AND is_customize = '1' AND delete_flag = '0'

SELECT screen_data_config_id, COUNT(*) as alarm_type_count FROM vm_screen_data_config WHERE screen_data_config_id IN
#{id}
AND data_type = '9' AND delete_flag = '0' GROUP BY screen_data_config_id

mapper.update:
UPDATE vm_screen_data_config_count SET alarm_type_num = CASE id
WHEN #{item.screenDataConfigId} THEN #{item.dataCode}
END, update_by = 'system', update_time = NOW() WHERE id IN
#{item.screenDataConfigId}

